<?php require_once __DIR__.'/../src/CarrierPortal.php';$portal=new CarrierPortal($db,$user);$appointments=$portal->appointments();$editing=null;foreach($appointments as $a)if($a['id']==($_GET['edit']??null))$editing=$a;if(isset($_GET['edit'])&&!$editing)throw new DomainException('Rendez-vous inaccessible.'); ?>
<div class="page-heading"><div><p class="context">Espace transporteur</p><h1>Mes rendez-vous</h1><p>Demandes de créneaux pour votre société. Les conflits et incompatibilités sont vérifiés à l’enregistrement.</p></div></div>
<section class="panel"><h2><?= $editing?'Modifier le rendez-vous':'Demander un rendez-vous' ?></h2><?php startForm('carrier_save',['id'=>$editing['id']??'']); ?><div class="form-grid"><?php inputField('reference','Référence',$editing['reference']??'');selectField('dock_id','Quai',$portal->resources('dock'),$editing['dock_id']??'');selectField('driver_id','Chauffeur',$portal->resources('driver'),$editing['driver_id']??'');selectField('vehicle_id','Véhicule',$portal->resources('vehicle'),$editing['vehicle_id']??'');selectField('trailer_id','Remorque',$portal->resources('vehicle'),$editing['trailer_id']??'',true);selectField('operation','Opération',[['id'=>'reception','label'=>'Réception'],['id'=>'expedition','label'=>'Expédition']],$editing['operation']??'reception');inputField('starts_at','Début',str_replace(' ','T',$editing['starts_at']??''),'datetime-local');inputField('ends_at','Fin',str_replace(' ','T',$editing['ends_at']??''),'datetime-local'); ?></div><button>Enregistrer le rendez-vous</button></form></section>
<section class="panel"><h2>Rendez-vous de votre société</h2><?php foreach($appointments as $a): ?><article><h3><?= h($a['reference']) ?></h3><p><?= h($a['starts_at'].' / '.$a['ends_at'].' · '.$a['dock_code'].' · '.$a['plate']) ?> <?= badge($a['status']) ?></p><?php if($a['status']==='active'): ?><a href="<?= h(url(['page'=>'carrier_portal','edit'=>$a['id']])) ?>">Modifier</a><?php startForm('carrier_cancel',['id'=>$a['id']]); ?><button class="secondary">Annuler le rendez-vous</button></form><?php endif; ?></article><?php endforeach;if(!$appointments): ?><p class="empty">Aucun rendez-vous.</p><?php endif; ?></section>
